import asyncio
import json
from typing import Any, Dict
import fastmcp
import httpx


def create_mcp_server_from_openapi(
    openapi_spec: Dict[str, Any],
    http_client: httpx.AsyncClient
) -> fastmcp.Server:
    """
    Generate an MCP server whose tools mirror OpenAPI 3.0 operations.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a Python dict
        http_client: Configured httpx.AsyncClient with base_url already set

    Returns:
        fastmcp.Server with tools corresponding to each OpenAPI operation
    """
    server = fastmcp.Server("openapi-mcp")

    for path, path_item in openapi_spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path}")
            summary = operation.get("summary", f"{method.upper()} {path}")
            parameters = operation.get("parameters", [])
            has_request_body = "requestBody" in operation

            tool_handler = _create_operation_handler(
                http_client, method, path, parameters, has_request_body
            )

            server.tool(name=operation_id, description=summary)(tool_handler)

    return server


def _create_operation_handler(
    client: httpx.AsyncClient,
    method: str,
    path: str,
    parameters: list,
    has_request_body: bool
):
    """Factory to create a handler for a single OpenAPI operation."""

    async def handler(**kwargs) -> str:
        path_params: Dict[str, Any] = {}
        query_params: Dict[str, Any] = {}
        header_params: Dict[str, Any] = {}
        request_body = None

        for param in parameters:
            param_name = param["name"]
            if param_name not in kwargs:
                continue

            param_value = kwargs[param_name]
            param_in = param.get("in", "query")

            if param_in == "path":
                path_params[param_name] = param_value
            elif param_in == "query":
                query_params[param_name] = param_value
            elif param_in == "header":
                header_params[param_name] = param_value

        if has_request_body and "body" in kwargs:
            request_body = kwargs["body"]

        final_path = path
        for name, value in path_params.items():
            final_path = final_path.replace(f"{{{name}}}", str(value))

        response = await client.request(
            method=method.upper(),
            url=final_path,
            params=query_params if query_params else None,
            headers=header_params if header_params else None,
            json=request_body if request_body else None
        )

        response.raise_for_status()

        try:
            return json.dumps(response.json())
        except (json.JSONDecodeError, ValueError):
            return response.text

    return handler


async def main():
    example_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/users": {
                "get": {
                    "operationId": "listUsers",
                    "summary": "List all users",
                    "parameters": [
                        {"name": "limit", "in": "query", "schema": {"type": "integer"}}
                    ],
                    "responses": {"200": {"description": "OK"}}
                }
            },
            "/users/{userId}": {
                "get": {
                    "operationId": "getUser",
                    "summary": "Get user by ID",
                    "parameters": [
                        {"name": "userId", "in": "path", "required": True, "schema": {"type": "string"}}
                    ],
                    "responses": {"200": {"description": "OK"}}
                }
            }
        }
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = create_mcp_server_from_openapi(example_spec, client)
        async with server.run() as mcp:
            await asyncio.sleep(3600)


if __name__ == "__main__":
    asyncio.run(main())

